source("pre.R"); suppressPackageStartupMessages(library(data.table))
cat("bit64 loaded at start:", "bit64" %in% loadedNamespaces(), "\n")
ch <- as.character
x <- int64(c("-9223372036854775807","-2","-1","0","9007199254740993",NA,"-1","-2")); cv <- ch(x)
dt <- data.table(k = x, a = 1:8)
show("class col", class(dt$k)); show("print", print(dt))
show("by=k", dt[, .(s = sum(a)), by = k]); 
show("by k class", class(dt[, .(s = sum(a)), by = k]$k))
show("sum by", {r <- dt[, .(s = sum(k)), by = .(g = a %% 2)]; list(class(r$s), ch(r$s))})
show("max by", {r <- tryCatch(dt[, .(s = max(k, na.rm=TRUE)), by = .(g = a %% 2)], error=function(e) conditionMessage(e)); if (is.data.frame(r)) list(class(r$s), ch(int64(r$s))) else r})
show("setkey", {d2 <- copy(dt); setkey(d2, k); list(class(d2$k), ch(d2$k))})
show("order", ch(dt[order(k)]$k)); show("order -k", tryCatch(ch(dt[order(-k)]$k), error=function(e) conditionMessage(e)))
show("unique", ch(unique(dt, by="k")$k)); show("uniqueN", uniqueN(dt$k)); show("duplicated", duplicated(dt, by="k"))
show("filter", ch(dt[k == int64(-1)]$k)); show("filter %in%", ch(dt[k %in% int64(c(-1,-2))]$k)); show("is.na filter", dt[is.na(k), a])
show(":=", {d2 <- copy(dt); d2[, z := k + 1L]; list(class(d2$z), ch(d2$z))})
show(":= sub", {d2 <- copy(dt); d2[a == 2, k := int64(7)]; list(class(d2$k), ch(d2$k))})
show(":= NA", {d2 <- copy(dt); d2[a == 2, k := NA]; list(class(d2$k), ch(d2$k), is.na(d2$k))})
show(":= int", {d2 <- copy(dt); d2[a == 2, k := 5L]; list(class(d2$k), ch(d2$k))})
show(":= dbl", {d2 <- copy(dt); d2[a == 2, k := 5]; list(class(d2$k), ch(d2$k))})
show("join on", {r <- dt[data.table(k = int64(c(-1, 5, NA)), b = 1:3), on = "k"]; r})
show("join nomatch NULL", dt[data.table(k = int64(c(-1, 5)), b = 1:2), on = "k", nomatch = NULL])
show("join value pad", {r <- data.table(id = 1:3)[data.table(id = c(1L, 3L), v = x[2:3]), on = "id", v := i.v]; list(class(r$v), ch(r$v), is.na(r$v))})
show("join value pad2", {r <- data.table(id = c(1L, 3L), v = x[2:3])[data.table(id = 1:3), on = "id"]; list(class(r$v), ch(r$v), is.na(r$v))})
show("merge all", {r <- merge(data.table(k=x[1:3], a=1:3), data.table(k=x[3:5], b=1:3), by="k", all=TRUE); list(class(r$k), ch(r$k), r$a, r$b)})
show("rbindlist", {r <- rbindlist(list(data.table(k=x[1:2]), data.table(k=x[3]))); list(class(r$k), ch(r$k))})
show("rbindlist fill", {r <- rbindlist(list(data.table(a=1), data.table(a=2, k=x[3])), fill=TRUE); list(class(r$k), ch(r$k), is.na(r$k))})
show("rbindlist mix integer", {r <- tryCatch(rbindlist(list(data.table(k=x[1:2]), data.table(k=3L))), error=function(e) conditionMessage(e)); if (is.data.frame(r)) list(class(r$k), ch(r$k)) else r})
show("rbindlist mix integer64", {r <- tryCatch(rbindlist(list(data.table(k=x[1:2]), data.table(k=as_integer64(int64(3))))), error=function(e) conditionMessage(e)); if (is.data.frame(r)) list(class(r$k), ch(int64(r$k))) else r})
show("rbindlist integer64 first", {r <- tryCatch(rbindlist(list(data.table(k=as_integer64(int64(3))), data.table(k=x[1:2]))), error=function(e) conditionMessage(e)); if (is.data.frame(r)) list(class(r$k), ch(int64(r$k))) else r})
show("dcast/shift", {r <- dt[, .(l = shift(k))]; list(class(r$l), ch(r$l), is.na(r$l))})
show("shift fill", {r <- tryCatch(shift(x, fill = int64(0)), error=function(e) conditionMessage(e)); list(class(r), tryCatch(ch(r), error=function(e) "?"))})
show("fifelse", {r <- tryCatch(fifelse(dt$a > 4, dt$k, int64(0)), error=function(e) conditionMessage(e)); list(class(r), ch(r))})
show("fcoalesce", {r <- tryCatch(fcoalesce(x, int64(0)), error=function(e) conditionMessage(e)); list(class(r), ch(r))})
show("nafill", {r <- tryCatch(nafill(x, fill = 0), error=function(e) conditionMessage(e)); list(class(r), tryCatch(ch(r), error=function(e) "?"))})
show("setorder", {d2 <- copy(dt); setorder(d2, k); ch(d2$k)}); show("setorder -k", {d2 <- copy(dt); setorder(d2, -k); ch(d2$k)})
show("frank", frank(x)); show("fsort", tryCatch(ch(fsort(x)), error=function(e) conditionMessage(e)))
show("dt[NA row]", {r <- dt[c(1, NA)]; list(ch(r$k), is.na(r$k))}); show("dt[10]", {r <- dt[10]; list(ch(r$k), is.na(r$k))})
show(".SD lapply sum", {r <- dt[, lapply(.SD, sum, na.rm=TRUE), .SDcols="k"]; list(class(r$k), ch(r$k))})
show("melt", {r <- tryCatch(melt(data.table(id=1:2, p=x[2:3], q=x[4:5]), id.vars="id"), error=function(e) conditionMessage(e)); if (is.data.frame(r)) list(class(r$value), ch(r$value)) else r})
show("dcast", {r <- tryCatch(dcast(data.table(id=c(1,1,2), nm=c("a","b","a"), v=x[2:4]), id ~ nm, value.var="v"), error=function(e) conditionMessage(e)); if (is.data.frame(r)) list(class(r$b), ch(r$b), is.na(r$b)) else r})
show("as.data.table(df)", class(as.data.table(data.frame(k=x))$k)); show("set()", {d2 <- copy(dt); set(d2, 1L, "k", int64(99)); ch(d2$k)})
show("bit64 loaded at end:", "bit64" %in% loadedNamespaces())
for (w in list(uint64(c("18446744073709551614","1",NA,"1")), int128(c("-1","18446744073709551616",NA,"-1")))) { cat("-----", class(w)[1], "\n"); cw <- ch(w)
 d <- tryCatch(data.table(k = w, a = 1:4), error=function(e) {cat("ctor ERR", conditionMessage(e), "\n"); NULL}); if (is.null(d)) next
 show("class", class(d$k)); show("by", tryCatch({r <- d[, .N, by = k]; list(class(r$k), ch(r$k), r$N)}, error=function(e) conditionMessage(e)))
 show("order", tryCatch(ch(d[order(k)]$k), error=function(e) conditionMessage(e))); show("setkey", tryCatch({d2 <- copy(d); setkey(d2, k); ch(d2$k)}, error=function(e) conditionMessage(e)))
 show("unique", tryCatch(ch(unique(d, by="k")$k), error=function(e) conditionMessage(e))); show("join", tryCatch({r <- d[data.table(k = w[2:3], b = 1:2), on = "k"]; list(ch(r$k), r$a)}, error=function(e) conditionMessage(e)))
 show("rbindlist fill", tryCatch({r <- rbindlist(list(data.table(a=1), data.table(a=2, k=w[1])), fill=TRUE); list(class(r$k), ch(r$k), is.na(r$k))}, error=function(e) conditionMessage(e)))
 show("d[NA]", tryCatch({r <- d[c(1,NA)]; list(class(r$k), ch(r$k), is.na(r$k))}, error=function(e) conditionMessage(e)))
 show("filter", tryCatch(d[k == w[2], a], error=function(e) conditionMessage(e))); show("shift", tryCatch({r <- shift(w); list(class(r), ch(r))}, error=function(e) conditionMessage(e)))
 show(":= NA", tryCatch({d2 <- copy(d); d2[a == 2, k := NA]; list(class(d2$k), ch(d2$k))}, error=function(e) conditionMessage(e)))
 show("print", print(d))
}
